:root {
    --bg-dark: #070913;
    --sidebar-bg: rgba(11, 15, 30, 0.65);
    --card-bg: rgba(20, 27, 50, 0.45);
    --card-border: rgba(255, 255, 255, 0.06);
    --primary: #1f1633;
    --primary-hover: #291d42;
    --primary-glow: rgba(92, 84, 236, 0.25);
    --secondary: rgba(255, 255, 255, 0.08);
    --secondary-hover: rgba(255, 255, 255, 0.15);
    --success: #10b910;
    --success-glow: rgba(16, 185, 129, 0.2);
    --error: #f43f5e;
    --error-glow: rgba(244, 63, 94, 0.2);
    --text-main: #f1f5f9;
    --text-muted: #94a3b8;
    --font-sans: 'Outfit', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-dark);
    color: var(--text-main);
    font-family: var(--font-sans);
    overflow: hidden;
    height: 100vh;
    width: 100vw;
    position: relative;
}

.glow-orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(140px);
    z-index: 0;
    pointer-events: none;
    opacity: 0.45;
}

.orb-1 {
    top: -10%;
    right: 15%;
    width: 400px;
    height: 400px;
    background: var(--primary-glow);
}

.orb-2 {
    bottom: 5%;
    left: 10%;
    width: 350px;
    height: 350px;
    background: rgba(16, 185, 129, 0.15);
}

.orb-3 {
    top: 40%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 500px;
    height: 500px;
    background: rgba(99, 102, 241, 0.08);
}

.cockpit-container {
    display: grid;
    grid-template-columns: 260px 1fr;
    height: 100vh;
    width: 100vw;
    position: relative;
    z-index: 1;
}

.cockpit-sidebar {
    background: var(--sidebar-bg);
    border-right: 1px solid var(--card-border);
    backdrop-filter: blur(25px);
    display: flex;
    flex-direction: column;
    padding: 1.75rem 1.25rem;
    justify-content: space-between;
}

.brand {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 2rem;
}

.brand .logo {
    background: linear-gradient(135deg, #818cf8 0%, #4f46e5 100%);
    width: 38px;
    height: 38px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.25rem;
    font-weight: 800;
    box-shadow: 0 4px 12px var(--primary-glow);
}

.brand-text h2 {
    font-size: 1.15rem;
    font-weight: 700;
    letter-spacing: 0.5px;
}

.brand-text span {
    font-size: 0.65rem;
    color: var(--text-muted);
    font-weight: 600;
    letter-spacing: 1px;
}

.system-status {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--card-border);
    border-radius: 12px;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 2rem;
}

.status-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.status-dot {
    width: 8px;
    height: 8px;
    background-color: var(--text-muted);
    border-radius: 50%;
    display: inline-block;
    transition: var(--transition);
}

.status-dot.green {
    background-color: var(--success);
    box-shadow: 0 0 8px var(--success);
}

.status-dot.red {
    background-color: var(--error);
    box-shadow: 0 0 8px var(--error);
}

.status-text {
    font-size: 0.75rem;
    font-weight: 500;
    color: var(--text-muted);
}

.sidebar-nav {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    flex-grow: 1;
}

.nav-btn {
    background: transparent;
    border: none;
    outline: none;
    color: var(--text-muted);
    font-family: var(--font-sans);
    font-size: 0.9rem;
    font-weight: 500;
    text-align: left;
    padding: 0.75rem 1rem;
    border-radius: 10px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    transition: var(--transition);
}

.nav-btn svg {
    opacity: 0.7;
    transition: var(--transition);
}

.nav-btn:hover {
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
    background: rgba(146, 146, 146, 0.03);
    color: var(--text-main);
}

.nav-btn.active {
    background: var(--primary);
    color: var(--text-main);
}

.nav-btn.active:hover {
    background: var(--primary-hover);
    color: var(--text-main);
}

.nav-btn.active svg {
    opacity: 1;
}

.sidebar-footer {
    font-size: 0.7rem;
    color: var(--text-muted);
    text-align: center;
    border-top: 1px solid var(--card-border);
    padding-top: 1rem;
    margin-top: auto;
}

.sidebar-footer-link {
    color: var(--text-muted);
    text-decoration: none;
    transition: var(--transition);
    cursor: pointer;
    font-weight: 500;
    display: inline-block;
}

.sidebar-footer-link:hover {
    color: #a5b4fc;
    text-shadow: 0 0 8px rgba(129, 140, 248, 0.5);
}

.cockpit-main {
    padding: 2.25rem 2.5rem;
    overflow-y: auto;
    height: 100vh;
}

.tab-content {
    display: none;
    animation: fadeIn 0.4s ease;
}

.tab-content.active {
    display: block;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(6px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.header-banner {
    margin-bottom: 2rem;
}

.header-banner h2 {
    font-size: 1.75rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    margin-bottom: 0.25rem;
    background: linear-gradient(135deg, #fff 30%, #a5b4fc 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.header-banner p {
    color: var(--text-muted);
    font-size: 0.95rem;
}

.glass-card {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 18px;
    backdrop-filter: blur(15px);
    padding: 1.75rem;
    position: relative;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.card-title {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 1.25rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.card-title::before {
    content: '';
    display: inline-block;
    width: 4px;
    height: 14px;
    background: var(--primary);
    border-radius: 2px;
}

.control-grid {
    display: grid;
    grid-template-columns: 1.3fr 1fr;
    gap: 1.75rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1rem;
}

label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    margin-bottom: 0.5rem;
}

input {
    width: 100%;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    color: var(--text-main);
    font-family: var(--font-sans);
    padding: 0.75rem 1rem;
    font-size: 0.9rem;
    outline: none;
    transition: var(--transition);
}

input:focus {
    background: rgba(255, 255, 255, 0.06);
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.3);
}

select {
    width: 100%;
    background: rgba(20, 27, 50, 0.5);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    color: var(--text-main);
    font-family: var(--font-sans);
    padding: 0.85rem 1.25rem;
    font-size: 0.9rem;
    outline: none;
    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23818cf8'%3E%3Cpath d='M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6 1.41-1.41z'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right 1.25rem center;
    background-size: 1.3rem;
    padding-right: 2.75rem;
    cursor: pointer;
    backdrop-filter: blur(12px);
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.15);
}

select:hover {
    background-color: rgba(20, 27, 50, 0.7);

    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
    transform: translateY(-1px);
}

select:focus {
    border-color: var(--primary);
    background-color: rgba(11, 15, 30, 0.8);
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.3);
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%236366f1'%3E%3Cpath d='M7.41 15.41L12 10.83l4.59 4.58L18 14l-6-6-6 6 1.41 1.41z'/%3E%3C/svg%3E");
}

select option {
    background-color: #0b0f19;
    color: #f1f5f9;
    padding: 0.9rem;
    font-size: 0.9rem;
}

select optgroup {
    background-color: #0a0d18;
    color: #818cf8;
    font-weight: 700;
    font-size: 0.75rem;
    letter-spacing: 0.75px;
    padding: 0.65rem 0.5rem;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

select optgroup option {
    color: #e2e8f0;
    font-weight: 400;
    text-transform: none;
    padding-left: 1.25rem;
    background-color: #0b0f19;
}

.env-preview-card {
    background: rgba(92, 84, 236, 0.03);
    border: 1px dashed rgba(92, 84, 236, 0.25);
    border-radius: 10px;
    padding: 0.75rem 1.15rem;
    margin-top: 1.15rem;
    margin-bottom: 1.15rem;
    display: flex;
    align-items: center;
    gap: 0.65rem;
    transition: var(--transition);
    animation: pulseGlow 3s infinite ease-in-out;
}

.env-preview-card:hover {
    background: rgba(92, 84, 236, 0.07);

}

.env-preview-card .preview-icon {
    font-size: 1.05rem;
}

.env-preview-card .preview-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--text-muted);
    letter-spacing: 0.3px;
}

.env-preview-card .preview-url {
    font-family: var(--font-mono);
    font-size: 0.8rem;
    font-weight: 600;
    color: #818cf8;

    word-break: break-all;
}


.btn {
    font-family: var(--font-sans);
    font-size: 0.9rem;
    font-weight: 600;
    padding: 0.8rem 1.5rem;
    border-radius: 10px;
    border: none;
    outline: none;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    transition: var(--transition);
}

.btn-sm {
    padding: 0.4rem 0.9rem;
    font-size: 0.75rem;
}

.btn-primary {
    background: var(--primary);
    color: var(--text-main);
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
}

.btn-primary:hover {
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
    background: var(--primary-hover);
    transform: translateY(-1px);
}

.btn-secondary {
    background: var(--secondary);
    color: var(--text-main);
    border: 1px solid var(--card-border);
}

.btn-secondary:hover {
    background: var(--secondary-hover);
}

.btn-danger {
    background: var(--error);
    color: var(--text-main);
    box-shadow: 0 4px 15px var(--error-glow);
}

.btn-danger:hover {
    background: #e12d4c;
}

.btn-success {
    background: var(--success);
    color: var(--text-main);
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
}

.btn-success:hover {
    background: #7fd310;
}

.hidden {
    display: none !important;
}

.status-panel {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.test-progress-indicator {
    position: relative;
    width: 140px;
    height: 140px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1.5rem;
}

.pulse-ring {
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    border: 3px dashed var(--card-border);
}

.pulse-ring.running {
    border: 3px solid var(--primary);
    border-right-color: transparent;
    animation: rotate 2s linear infinite;
}

@keyframes rotate {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

.indicator-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.status-badge {
    background: rgba(255, 255, 255, 0.05);
    padding: 0.2rem 0.6rem;
    border-radius: 999px;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    margin-bottom: 0.25rem;
}

.timer {
    font-size: 1.75rem;
    font-weight: 800;
    font-family: var(--font-mono);
}

.status-details {
    width: 100%;
    border-top: 1px solid var(--card-border);
    padding-top: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.stat-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    align-items: center;
}

.stat-row span {
    color: var(--text-muted);
}

.progress-bar-container {
    width: 120px;
    height: 6px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 3px;
    overflow: hidden;
}

.progress-bar-fill {
    height: 100%;
    background: var(--primary);
    border-radius: 3px;
    width: 0%;
    transition: width 0.4s ease;
}

.logs-grid {
    display: grid;
    grid-template-rows: 1fr 1fr;
    gap: 1.5rem;
    height: calc(100vh - 160px);
}

.log-terminal-container {
    display: flex;
    flex-direction: column;
    padding: 1.25rem;
    height: 100%;
}

.terminal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--card-border);
    padding-bottom: 0.5rem;
    margin-bottom: 0.75rem;
}

.terminal-header .title {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--text-muted);
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

.terminal-search-box {
    display: flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--card-border);
    border-radius: 100px;
    height: 40px;
    padding: 0.2rem 0.5rem;
    gap: 0.35rem;
    transition: var(--transition);
}

.terminal-search-box:focus-within {

    background: rgba(255, 255, 255, 0.05);
}

.terminal-search-box input {
    background: transparent;
    border: none;
    outline: none;
    color: var(--text-main);
    font-size: 0.75rem;
    width: 100px;
    padding: 0.15rem 0.25rem;
    transition: var(--transition);
}

.terminal-search-box input:focus {
    width: 150px;
    box-shadow: none;
}

.search-counter {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--text-muted);
    min-width: 40px;
    text-align: center;
    user-select: none;
}

.btn-search-nav {
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-size: 0.65rem;
    cursor: pointer;
    padding: 0.15rem 0.3rem;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition);
}

.btn-search-nav:hover {
    background: rgba(255, 255, 255, 0.08);
    color: var(--text-main);
}

.log-highlight {
    background-color: rgba(234, 179, 8, 0.25);
    border-radius: 2px;
    border-bottom: 1.5px solid rgb(234, 179, 8);
    color: #fff;
    transition: var(--transition);
}

.log-highlight.active-highlight {
    background-color: rgba(244, 63, 94, 0.6);
    border-bottom: 1.5px solid #f43f5e;
    box-shadow: 0 0 8px rgba(244, 63, 94, 0.4);
    color: #fff;
}

.terminal {
    background: #020308;
    border-radius: 10px;
    flex-grow: 1;
    font-family: var(--font-mono);
    font-size: 0.8rem;
    color: #4ade80;
    padding: 0.75rem;
    overflow-y: auto;
    white-space: pre-wrap;
    word-break: break-all;
    position: relative;
    max-height: calc(50vh - 140px);
}

.terminal::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

.terminal::-webkit-scrollbar-track {
    background: rgba(2, 3, 8, 0.4);
    border-radius: 10px;
}

.terminal::-webkit-scrollbar-thumb {
    background: rgba(92, 84, 236, 0.3);
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.02);
    transition: var(--transition);
}

.terminal::-webkit-scrollbar-thumb:hover {
    background: rgba(92, 84, 236, 0.6);
}

.report-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1.5rem;
}

.report-header h2 {
    font-size: 1.5rem;
    font-weight: 800;
}

.report-frame-container {
    height: calc(100vh - 180px);
    padding: 0;
    overflow: hidden;
}

iframe {
    width: 100%;
    height: 100%;
    border: none;
    outline: none;
    border-radius: 18px;
}

.report-placeholder {
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    text-align: center;
}

.report-placeholder .icon {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.report-placeholder h3 {
    font-size: 1.2rem;
    margin-bottom: 0.5rem;
}

.report-placeholder p {
    color: var(--text-muted);
    max-width: 450px;
    font-size: 0.9rem;
}

.env-panel {
    overflow-y: auto;
}

.env-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--card-border);
    padding-bottom: 0.75rem;
    margin-bottom: 1.25rem;
}

.env-table {
    width: 100%;
    border-collapse: collapse;
}

.env-table th {
    text-align: left;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--card-border);
}

.env-table td {
    padding: 0.5rem 1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

.env-input-key {
    font-family: var(--font-mono);
    font-weight: 600;
    color: #a5b4fc;
}

.env-input-val {
    background: rgba(255, 255, 255, 0.02);
}

.env-value-wrapper {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
}

.env-value-wrapper .env-input-val {
    padding-right: 2.75rem;
}

.btn-toggle-val {
    position: absolute;
    right: 0.75rem;
    background: transparent;
    border: none;
    outline: none;
    color: var(--text-muted);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0.25rem;
    border-radius: 6px;
    transition: var(--transition);
}

.btn-toggle-val:hover {
    color: var(--text-main);
    background: rgba(255, 255, 255, 0.05);
}

.btn-toggle-val svg.hidden {
    display: none !important;
}

.mock-control-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.75rem;
}

.mock-status-banner {
    background: rgba(255, 255, 255, 0.02);
    border: 1px dashed var(--card-border);
    border-radius: 12px;
    padding: 2rem;
    text-align: center;
    margin-top: 1rem;
}

.status-indicator {
    display: block;
    font-size: 2.25rem;
    font-weight: 800;
    color: var(--text-muted);
    letter-spacing: 1px;
    margin-bottom: 0.5rem;
    transition: var(--transition);
}

.status-indicator.online {
    color: var(--success);
    text-shadow: 0 0 15px var(--success-glow);
}

.mock-status-banner p {
    font-size: 0.85rem;
    color: var(--text-muted);
}

.mock-activity-panel {
    display: flex;
    flex-direction: column;
}

.activity-feed {
    background: #020308;
    border-radius: 10px;
    padding: 1rem;
    flex-grow: 1;
    overflow-y: auto;
    font-family: var(--font-mono);
    font-size: 0.8rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    height: 300px;
}

.activity-item {
    color: var(--text-muted);
    border-left: 2px solid var(--card-border);
    padding-left: 0.5rem;
}

.activity-item.system {
    color: #a5b4fc;
    border-left-color: var(--primary);
}

.activity-item.request {
    color: #4ade80;
    border-left-color: var(--success);
}

/* cURL Scenario Generator Custom Styles */
