import { get } from "@pulse/http";
import { ps } from "@pulse/core";
import { catalogSchema } from "@src/schemas/catalog/catalog.schema";

export interface CatalogParams { baseUrl: string; token: string; }

export function getCatalog({ baseUrl, token }: CatalogParams) {
    const url = `${baseUrl}/catalog`;
    const res = get(url, { token }, 200, "getCatalog");

    ps.expect(res)
        .status(200)
        .bodyNotEmpty()
        .responseTimeLessThan(1000)
        .jsonSchema(catalogSchema);

    return res;
}

